import React, { useState } from "react";
import {
    Form,
    Button,
    Container,
    Row,
    Col,
    Card,
    Alert,
} from "react-bootstrap";
import axios from "axios";

const AuthPage = ({ onLoginSuccess }) => {
    const [isLogin, setIsLogin] = useState(true);
    const [showRoleSelection, setShowRoleSelection] = useState(false);

    const [username, setUsername] = useState("");
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [confirmPassword, setConfirmPassword] = useState("");
    const [role, setRole] = useState("");
    const [error, setError] = useState("");
    const [isLoading, setIsLoading] = useState(false);

    // --- Student-specific fields ---
    const [studentNumber, setStudentNumber] = useState("");
    const [name, setName] = useState("");
    const [surname, setSurname] = useState("");
    const [gender, setGender] = useState("");
    const [dob, setDob] = useState("");
    const [address, setAddress] = useState("");
    const [phone, setPhone] = useState("");

    // === LOGIN HANDLER ===
    const handleLogin = async (e) => {
        e.preventDefault();

        if (!email || !password) {
            setError("Please fill in all fields");
            return;
        }

        setIsLoading(true);
        setError("");

        try {
            const response = await axios.post("https://localhost:7281/api/Authentication/Login", {
                email,
                password,
            });

            if (response.data && response.data.role) {
                const { role, token } = response.data;
                localStorage.setItem("token", token);
                localStorage.setItem("role", role);
                onLoginSuccess(role);
            } else {
                setError("Unexpected server response. Please try again.");
            }
        } catch (error) {
            if (error.response) {
                if (error.response.status === 401) setError("Invalid email or password.");
                else if (error.response.status === 404) setError("User not found. Please register first.");
                else setError(error.response.data.message || "Login failed. Please try again.");
            } else {
                setError("Unable to connect to the server. Check your backend is running.");
            }
        } finally {
            setIsLoading(false);
        }
    };

    // === REGISTER HANDLER ===
    const handleRegister = async (e) => {
        e.preventDefault();

        // validation
        if (role === "Student") {
            if (!name || !surname || !gender || !dob || !address || !email || !password || !confirmPassword) {
                setError("Please fill in all required fields for Student.");
                return;
            }
        } else {
            if (!username || !email || !password || !confirmPassword) {
                setError("Please fill in all required fields.");
                return;
            }
        }

        if (password !== confirmPassword) {
            setError("Passwords do not match");
            return;
        }

        setIsLoading(true);
        setError("");

        let userData = {};
        if (role === "Student") {
            userData = {
                name : name,
                surname : surname,
                gender : gender,
                dateOfBirth: dob,
                homeAddress: address,
                email : email,
                phone : phone,
                password : password,
                courseid : "555896b5-bf48-4960-6644-08ddfdd723ed" // Default course ID, adjust as necessary
            };
        } else {
            userData = { username, email, password };
        }

        let apiUrl = "";
        switch (role) {
            case "Admin":
                apiUrl = "https://localhost:7281/api/Authentication/Register?role=Admin";
                break;
            case "Lecturer":
                apiUrl = "https://localhost:7013/api/Authentication?role=Lecturer";
                break;
            case "Student":
                apiUrl = "https://localhost:7013/api/Authentication?role=Student";
                break;
            default:
                setError("Invalid role selected");
                setIsLoading(false);
                return;
        }

        try {
            await axios.post(apiUrl, userData);
            alert(`Registration successful as ${role}`);
            // Reset all fields
            setUsername("");
            setEmail("");
            setPassword("");
            setConfirmPassword("");
            setRole("");
            setStudentNumber("");
            setName("");
            setSurname("");
            setGender("");
            setDob("");
            setAddress("");
            setPhone("");
            setIsLogin(true);
            setShowRoleSelection(false);
        } catch (error) {
            setError(error.response?.data?.message || "Registration failed. Please try again.");
        } finally {
            setIsLoading(false);
        }
    };

    // === ROLE SELECTION HANDLER ===
    const handleRoleSelect = (selectedRole) => {
        setRole(selectedRole);
        setShowRoleSelection(false);
        setIsLogin(false);
    };

    return (
        <div
            style={{
                backgroundImage: "url('/images/WhatsApp Image 2025-10-02 at 11.28.03 AM.jpeg')",
                backgroundSize: "cover",
                backgroundPosition: "center",
                height: "100vh",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
            }}
        >
            <Container>
                <Row className="justify-content-center">
                    <Col xs={12} sm={8} md={6} lg={4}>
                        <Card
                            className="shadow p-4"
                            style={{
                                borderRadius: "15px",
                                backgroundColor: "rgba(255,255,255,0.95)",
                            }}
                        >
                            {showRoleSelection ? (
                                <>
                                    <h3 className="text-center mb-4">Choose Your Role</h3>
                                    <Button
                                        variant="outline-primary"
                                        className="w-100 mb-3"
                                        onClick={() => handleRoleSelect("Admin")}
                                    >
                                        Admin
                                    </Button>
                                    <Button
                                        variant="outline-success"
                                        className="w-100 mb-3"
                                        onClick={() => handleRoleSelect("Lecturer")}
                                    >
                                        Lecturer
                                    </Button>
                                    <Button
                                        variant="outline-warning"
                                        className="w-100 mb-3"
                                        onClick={() => handleRoleSelect("Student")}
                                    >
                                        Student
                                    </Button>
                                    <div className="text-center">
                                        <small>
                                            Already have an account?{" "}
                                            <span
                                                style={{ color: "#007bff", cursor: "pointer" }}
                                                onClick={() => {
                                                    setShowRoleSelection(false);
                                                    setIsLogin(true);
                                                }}
                                            >
                                                Log in
                                            </span>
                                        </small>
                                    </div>
                                </>
                            ) : isLogin ? (
                                <>
                                    <h3 className="text-center mb-4">Log in to Portal</h3>
                                    {error && <Alert variant="danger">{error}</Alert>}
                                    <Form onSubmit={handleLogin}>
                                        <Form.Group className="mb-3">
                                            <Form.Control
                                                type="email"
                                                placeholder="Email address"
                                                value={email}
                                                onChange={(e) => setEmail(e.target.value)}
                                                disabled={isLoading}
                                            />
                                        </Form.Group>
                                        <Form.Group className="mb-3">
                                            <Form.Control
                                                type="password"
                                                placeholder="Password"
                                                value={password}
                                                onChange={(e) => setPassword(e.target.value)}
                                                disabled={isLoading}
                                            />
                                        </Form.Group>
                                        <Button
                                            variant="primary"
                                            type="submit"
                                            className="w-100 mb-3"
                                            disabled={isLoading}
                                        >
                                            {isLoading ? "Logging in..." : "Login"}
                                        </Button>
                                        <div className="text-center">
                                            <small>
                                                Don’t have an account?{" "}
                                                <span
                                                    style={{ color: "#007bff", cursor: "pointer" }}
                                                    onClick={() => setShowRoleSelection(true)}
                                                >
                                                    Sign up
                                                </span>
                                            </small>
                                        </div>
                                    </Form>
                                </>
                            ) : (
                                <>
                                    <h3 className="text-center mb-4">Sign up as {role}</h3>
                                    {error && <Alert variant="danger">{error}</Alert>}
                                    <Form onSubmit={handleRegister}>
                                        {role === "Student" ? (
                                            <>
                                                <Form.Group className="mb-3">
                                                    <Form.Control
                                                        type="text"
                                                        placeholder="Name"
                                                        value={name}
                                                        onChange={(e) => setName(e.target.value)}
                                                        disabled={isLoading}
                                                    />
                                                </Form.Group>
                                                <Form.Group className="mb-3">
                                                    <Form.Control
                                                        type="text"
                                                        placeholder="Surname"
                                                        value={surname}
                                                        onChange={(e) => setSurname(e.target.value)}
                                                        disabled={isLoading}
                                                    />
                                                </Form.Group>
                                                <Form.Group className="mb-3">
                                                    <Form.Select
                                                        value={gender}
                                                        onChange={(e) => setGender(e.target.value)}
                                                        disabled={isLoading}
                                                    >
                                                        <option value="">-- Select Gender --</option>
                                                        <option value="Male">Male</option>
                                                        <option value="Female">Female</option>
                                                        <option value="Other">Other</option>
                                                    </Form.Select>
                                                </Form.Group>
                                                <Form.Group className="mb-3">
                                                    <Form.Control
                                                        type="date"
                                                        placeholder="Date of Birth"
                                                        value={dob}
                                                        onChange={(e) => setDob(e.target.value)}
                                                        disabled={isLoading}
                                                    />
                                                </Form.Group>
                                                <Form.Group className="mb-3">
                                                    <Form.Control
                                                        type="text"
                                                        placeholder="Home Address"
                                                        value={address}
                                                        onChange={(e) => setAddress(e.target.value)}
                                                        disabled={isLoading}
                                                    />
                                                </Form.Group>
                                                <Form.Group className="mb-3">
                                                    <Form.Control
                                                        type="email"
                                                        placeholder="Email Address"
                                                        value={email}
                                                        onChange={(e) => setEmail(e.target.value)}
                                                        disabled={isLoading}
                                                    />
                                                </Form.Group>
                                                <Form.Group className="mb-3">
                                                    <Form.Control
                                                        type="text"
                                                        placeholder="Phone Number (optional)"
                                                        value={phone}
                                                        onChange={(e) => setPhone(e.target.value)}
                                                        disabled={isLoading}
                                                    />
                                                </Form.Group>
                                            </>
                                        ) : (
                                            <>
                                                <Form.Group className="mb-3">
                                                    <Form.Control
                                                        type="text"
                                                        placeholder="Username"
                                                        value={username}
                                                        onChange={(e) => setUsername(e.target.value)}
                                                        disabled={isLoading}
                                                    />
                                                </Form.Group>
                                                <Form.Group className="mb-3">
                                                    <Form.Control
                                                        type="email"
                                                        placeholder="Email address"
                                                        value={email}
                                                        onChange={(e) => setEmail(e.target.value)}
                                                        disabled={isLoading}
                                                    />
                                                </Form.Group>
                                            </>
                                        )}

                                        <Form.Group className="mb-3">
                                            <Form.Control
                                                type="password"
                                                placeholder="Password"
                                                value={password}
                                                onChange={(e) => setPassword(e.target.value)}
                                                disabled={isLoading}
                                            />
                                        </Form.Group>
                                        <Form.Group className="mb-3">
                                            <Form.Control
                                                type="password"
                                                placeholder="Confirm password"
                                                value={confirmPassword}
                                                onChange={(e) => setConfirmPassword(e.target.value)}
                                                disabled={isLoading}
                                            />
                                        </Form.Group>

                                        <Button
                                            variant="success"
                                            type="submit"
                                            className="w-100 mb-3"
                                            disabled={isLoading}
                                        >
                                            {isLoading ? "Registering..." : `Register as ${role}`}
                                        </Button>

                                        <div className="text-center">
                                            <small>
                                                Already have an account?{" "}
                                                <span
                                                    style={{ color: "#007bff", cursor: "pointer" }}
                                                    onClick={() => setIsLogin(true)}
                                                >
                                                    Log in
                                                </span>
                                            </small>
                                        </div>
                                    </Form>
                                </>
                            )}
                        </Card>
                    </Col>
                </Row>
            </Container>
        </div>
    );
};

export default AuthPage;
